<script setup>
import { computed, ref, watch } from 'vue';
import Icon from '../components/Icon.vue'; import EventTable from '../components/EventTable.vue';
import { data, events, employees, byId, canControl, saveRecord, notify, employeeName, roomName } from '../store.js';
import { idEqual, localDateParts } from '../domain.js'; import { dateTime, downloadCsv } from '../format.js';
const query = ref(''), room = ref(''), department = ref(''), result = ref(''), from = ref(''), to = ref(''), onlyOpen = ref(false), page = ref(1);
const filtered = computed(() => events.value.filter(e => employeeName(e.employeeId).toLowerCase().includes(query.value.toLowerCase()) && (!room.value || idEqual(e.roomId, room.value)) && (!department.value || idEqual(byId('employees', e.employeeId)?.departmentId, department.value)) && (!result.value || e.result === result.value) && (!from.value || localDateParts(e.timestamp).date >= from.value) && (!to.value || localDateParts(e.timestamp).date <= to.value) && (!onlyOpen.value || e.result === 'denied' && !e.reviewed)).slice().sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp)));
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / 15)));
const rows = computed(() => filtered.value.slice((page.value - 1) * 15, page.value * 15));
watch([query, room, department, result, from, to, onlyOpen], () => { page.value = 1; });
const openViolations = computed(() => events.value.filter(e => e.result === 'denied' && !e.reviewed).slice().sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp)));
async function review(event) { try { await saveRecord('access_events', { id: event.id, reviewed: true, reviewedAt: new Date().toISOString() }); notify('Нарушение отмечено как просмотренное.'); } catch (e) { notify(e.message, 'error'); } }
function exportEvents() { downloadCsv('Журнал проходов.csv', [['Дата и время (МСК)', 'Сотрудник', 'Подразделение', 'Помещение', 'Направление', 'Результат', 'Причина', 'Способ проверки'], ...filtered.value.map(e => [dateTime(e.timestamp), employeeName(e.employeeId), byId('departments', byId('employees', e.employeeId)?.departmentId)?.name, roomName(e.roomId), e.direction === 'entry' ? 'Вход' : 'Выход', e.result === 'allowed' ? 'Разрешён' : 'Отказ', e.reason, e.source === 'photo' ? 'Фото' : 'Ручная имитация'])]); }
</script>
<template><div class="page-header"><div><span class="eyebrow">МОНИТОРИНГ БЕЗОПАСНОСТИ</span><h1>Журнал событий<span class="heading-dot">.</span></h1><p>История проходов, отказов и нарушений доступа.</p></div><button class="button" :disabled="!filtered.length" @click="exportEvents"><Icon name="download" :size="17" />Экспорт CSV</button></div><section v-if="canControl && openViolations.length" class="violations-panel"><div class="violations-heading"><Icon name="alert" :size="21" /><div><h3>Требуют внимания <span class="counter">{{ openViolations.length }}</span></h3><p>Попытки доступа, которые ещё не просмотрены</p></div></div><div v-for="event in openViolations.slice(0, 3)" :key="event.id" class="violation-row"><div><strong>{{ employeeName(event.employeeId) }}</strong><p>{{ roomName(event.roomId) }} · {{ event.reason }}</p></div><span class="muted">{{ dateTime(event.timestamp) }}</span><button class="button small" @click="review(event)"><Icon name="check" :size="15" />Просмотрено</button></div></section><div class="filter-panel"><div class="toolbar"><label class="search-field"><Icon name="search" :size="17" /><input v-model="query" placeholder="Найти сотрудника…" aria-label="Поиск по сотруднику" /></label><select v-model="room" aria-label="Помещение"><option value="">Все помещения</option><option v-for="r in data.rooms" :key="r.id" :value="r.id">{{ r.name }}</option></select><select v-model="department" aria-label="Подразделение"><option value="">Все подразделения</option><option v-for="d in data.departments" :key="d.id" :value="d.id">{{ d.name }}</option></select><select v-model="result" aria-label="Результат проверки"><option value="">Все результаты</option><option value="allowed">Разрешённые</option><option value="denied">Отказы</option></select></div><div class="date-filter"><label>С<input v-model="from" type="date" aria-label="Начальная дата" /></label><label>По<input v-model="to" type="date" aria-label="Конечная дата" /></label><label class="checkbox-label"><input v-model="onlyOpen" type="checkbox" />Только непросмотренные нарушения</label></div></div><section class="panel"><EventTable :items="rows" /><footer class="pagination"><span>Найдено событий: {{ filtered.length }}</span><div><button class="icon-button" aria-label="Предыдущая страница" :disabled="page <= 1" @click="page--"><Icon name="back" :size="17" /></button><span>{{ page }} / {{ pages }}</span><button class="icon-button" aria-label="Следующая страница" :disabled="page >= pages" @click="page++"><Icon name="arrow" :size="17" /></button></div></footer></section></template>
